+import javafx.scene.Node;
+import javafx.scene.layout.Background;
+import javafx.scene.layout.Pane;
+import javafx.scene.paint.Color;
+import javafx.stage.Stage;
+import com.oracle.test.manual.util.ManualTestWindow;
+
+/***
+ * Stage must initially only show on the OS taskbar, but not on the Screen.
+ * If the stage pops on the Screen and then iconifies, it's wrong.
+ *
+ * Note: Will not work on MacOS until https://bugs.openjdk.org/browse/JDK-8305675 is fixed
+ */
+public class StartIconified extends ManualTestWindow {
+
+    public StartIconified() {
+        super(
+            "StartIconified",
+            """
+            Verify:
+            1. The window must initially appear in the OS taskbar or dock.
+            (It is acceptable for the window to appear momentarily, then quickly get iconified.)
+            """,
+            700, 600);
+    }
+
+    @Override
+    protected Node createContent() {
+        Pane p = new Pane();
+        p.setBackground(Background.fill(Color.MAGENTA));
+        return p;
+    }
+
+    @Override
+    protected void prepareStage(Stage stage) {
+        super.prepareStage(stage);
+        stage.setIconified(true);
+    }
+}

